import type { Project } from '../project'
import { path, FileSystem, ts, tsc, TsMorphFileSystemWrapper } from '@servicenow/sdk-build-core'
import { projectHasScript, runScriptInProject } from './script-runner'
import { hasModuleLoader, isWebWorker } from './environment'

export const typeCheckProject = (project: Project) => {
    const logger = project.getLogger()
    const config = project.getConfig()
    const fs = project.getFileSystem()
    const clientDir = project.resolvePath(config.clientDir)

    if (config.clientDir && FileSystem.existsSync(fs, clientDir)) {
        const defaultCompilerOptions = {
            moduleResolution: ts.ModuleResolutionKind.Bundler,
            module: ts.ModuleKind.ES2022,
            target: ts.ScriptTarget.ES2022,
            lib: ['lib.es2022.d.ts', 'lib.dom.d.ts'],
            jsx: tsc.JsxEmit.Preserve,
        }
        const tsConfigFilePath = project.resolvePath(config.clientDir, 'tsconfig.json')
        const projectOptions: ts.ProjectOptions = {
            fileSystem: new TsMorphFileSystemWrapper(fs),
            defaultCompilerOptions,
        }
        if (FileSystem.existsSync(fs, tsConfigFilePath)) {
            logger.debug(`Using client tsconfig.json for type checking: ${tsConfigFilePath}`)
            projectOptions.tsConfigFilePath = tsConfigFilePath
            projectOptions.skipAddingFilesFromTsConfig = true
        } else {
            logger.warn('No client tsconfig.json found, using default compiler options for type checking')
        }
        const compiler = new ts.Project(projectOptions)
        logger.debug(`Type checking client project with options:
${JSON.stringify(compiler.getCompilerOptions(), null, 2)}`)

        const sourceFiles = compiler.addSourceFilesAtPaths([
            path.join(clientDir, '**/*.ts'),
            path.join(clientDir, '**/*.tsx'),
            path.join(clientDir, '**/*.d.ts'),
            '!**/node_modules/**',
        ])
        logger.debug(`Type checking ${sourceFiles.length} client source files:
${sourceFiles.map((file) => `  - ${file.getFilePath()}`).join('\n')}`)
        const diagnostics = compiler.getPreEmitDiagnostics()
        if (diagnostics.length > 0) {
            throw new Error(`Type check failed!
${compiler.formatDiagnosticsWithColorAndContext(diagnostics)}`)
        } else {
            logger.info('Type check completed successfully')
        }
    }
}

export async function uiPrebuild({ project }: { project: Project }): Promise<void> {
    const logger = project.getLogger()
    const config = project.getConfig()
    const fs = project.getFileSystem()

    typeCheckProject(project)

    const hasPrebuildScript = projectHasScript(project, 'prebuild')
    const supportsTaskScripts = !isWebWorker || hasModuleLoader()
    if (supportsTaskScripts && hasPrebuildScript) {
        await runScriptInProject({
            scriptName: 'prebuild',
            project: project,
            throwIfNotFound: false,
        })
    } else if (config.clientDir) {
        if (hasPrebuildScript) {
            logger.debug('Custom scripts are not supported, so using the default UI build')
        }
        // This needs to be imported dynamically to avoid sass bundling issues
        const { defaultUiBuild } = await import('./default-ui-build.js')
        await defaultUiBuild({ project: project })
    }
    if (FileSystem.existsSync(fs, project.resolvePath(config.staticContentDir))) {
        for (const file of project.reloadDirectory(config.staticContentDir)) {
            // static content files are output from the prebuild process
            // and should be treated as read-only by the project
            file.setReadOnly(true)
        }
    }
}

export async function uiPostbuild({ project }: { project: Project }): Promise<void> {
    const logger = project.getLogger()

    const supportsTaskScripts = !isWebWorker || hasModuleLoader()

    if (supportsTaskScripts) {
        await runScriptInProject({
            scriptName: 'postbuild',
            project: project,
            throwIfNotFound: false,
        })
    } else if (projectHasScript(project, 'postbuild')) {
        logger.warn('Custom scripts are not supported, skipping postbuild script')
    }
}
